module Panel(flag: boolean, bias: number) {
 const items: number[] = if (@flag) { [6] } else { [11, 17, 23] }
 export const count: number = @items.length
 for item in @items {
  point Mark = coordinate(x: @bias + @item, y: 2 * @item - @bias)
 }
}
instance First = Panel(flag: true, bias: 17)
instance Second = Panel(flag: false, bias: -41)
point Observe = coordinate(x: @First::count, y: @Second::count)

